    13	    public DocumentRenderer getRenderer(Reservation reservation) {
    14	        var room = roomService.getRoom(reservation.getRoomNumber());
    15	        if (reservation.getGuestCpf() != null) {
    16	            return new CpfReceiptRenderer(room);
    17	        } else if (reservation.getCompanyCnpj() != null) {
    18	            return new CnpjInvoiceRenderer(room);
    19	        } else if (reservation.getGuestPassport() != null) {
    20	            return new PassportReceiptRenderer(room);
    21	        } else {
    22	            throw new IllegalArgumentException("Reservation must have CPF, CNPJ, or Passport");
    23	        }
    24	    }
