    13	public class ReservationService {
    14	    private final Map<Integer, Reservation> reservations = new TreeMap<>();
    15	    private int nextReservationId = 1;
    16	    private final RoomService roomService;
    17	    private final PricingService pricingService;
    18	
    19	    public ReservationService(RoomService roomService, PricingService pricingService) {
    20	        this.roomService = roomService;
    21	        this.pricingService = pricingService;
    22	    }
    23	
    24	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    25	            String companyCnpj, String companyName, String guestPassport, String guestCountry, LocalDate checkIn,
    26	            LocalDate checkOut, int guests, RatePlan ratePlan) {
    27	
    28	        if (!roomService.roomExists(roomNumber)) {
    29	            throw new IllegalArgumentException("Room not found");
    30	        }
    31	
    32	        Room room = roomService.getRoom(roomNumber);
    33	
    34	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    35	            throw new IllegalArgumentException("Check-out must be after check-in");
    36	        }
    37	
    38	        if (guests < 1 || guests > room.type.capacity) {
    39	            throw new IllegalArgumentException("Invalid number of guests");
    40	        }
    41	
    42	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
    43	            throw new IllegalArgumentException("Room is unavailable for these dates");
    44	        }
    45	
    46	        var pricing = pricingService.calculatePrice(room.type.nightlyRate, checkIn, checkOut, ratePlan);
    47	
    48	        Reservation reservation = new Reservation(nextReservationId++, roomNumber, guestName, guestEmail, guestCpf,
    49	                companyCnpj, companyName, guestPassport, guestCountry, checkIn, checkOut, guests, ratePlan,
    50	                pricing.nights(), pricing.subtotal(), pricing.discount(), pricing.total());
    51	
    52	        reservations.put(reservation.getId(), reservation);
    53	        return reservation;
    54	    }
    55	
    56	    public Reservation getReservation(int id) {
    57	        return reservations.get(id);
    58	    }
    59	
    60	    public Reservation confirmReservation(int id, double amountPaid) {
    61	        Reservation res = reservations.get(id);
    62	        if (res == null) {
    63	            throw new IllegalArgumentException("Reservation not found");
    64	        }
    65	        res.confirm(amountPaid);
    66	        return res;
    67	    }
