     1	package com.pousada.document;
     2	
     3	import com.pousada.domain.Reservation;
     4	import com.pousada.domain.Room;
     5	import com.pousada.util.MoneyRounder;
     6	import java.time.format.DateTimeFormatter;
     7	
     8	public class CnpjInvoiceRenderer implements DocumentRenderer {
     9	    private final Room room;
    10	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    11	    private static final double ISS_RATE = 0.05;
    12	
    13	    public CnpjInvoiceRenderer(Room room) {
    14	        this.room = room;
    15	    }
    16	
    17	    @Override
    18	    public DocumentContent render(Reservation reservation) {
    19	        String checkInFormatted = reservation.getCheckIn().format(DATE_FORMAT);
    20	        String checkOutFormatted = reservation.getCheckOut().format(DATE_FORMAT);
    21	
    22	        String nightsLabel = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
    23	
    24	        double iss = MoneyRounder.round(reservation.getTotal() * ISS_RATE);
    25	
    26	        StringBuilder sb = new StringBuilder();
    27	        sb.append(String.format("Fatura de hospedagem nº %d\n", reservation.getId()));
    28	        sb.append(String.format("Empresa: %s (CNPJ %s)\n", reservation.getCompanyName(),
    29	                reservation.getCompanyCnpj()));
    30	        sb.append(String.format("Hóspede: %s\n", reservation.getGuestName()));
    31	        sb.append(String.format("Quarto: %d (%s)\n", reservation.getRoomNumber(), room.type.name));
    32	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n", checkInFormatted, checkOutFormatted,
    33	                nightsLabel));
    34	        sb.append(String.format("Diárias: R$ %.2f\n", reservation.getSubtotal()));
    35	
    36	        if (reservation.getDiscount() > 0) {
    37	            sb.append(String.format("Desconto: R$ %.2f\n", reservation.getDiscount()));
    38	        }
    39	
    40	        sb.append(String.format("Total: R$ %.2f\n", reservation.getTotal()));
    41	        sb.append(String.format("ISS retido (5%%): R$ %.2f", iss));
    42	
    43	        String text = sb.toString();
    44	
    45	        return new DocumentContent(
    46	                "Fatura de hospedagem",
    47	                reservation.getId(),
    48	                reservation.getGuestName(),
    49	                null,
    50	                reservation.getCompanyCnpj(),
    51	                reservation.getCompanyName(),
    52	                null,
    53	                null,
    54	                reservation.getRoomNumber(),
    55	                room.type.name,
    56	                checkInFormatted,
    57	                checkOutFormatted,
    58	                reservation.getNights(),
    59	                reservation.getSubtotal(),
    60	                reservation.getDiscount(),
    61	                reservation.getTotal(),
    62	                text);
    63	    }
    64	}
