    87	    public Reservation cancelReservation(int id) {
    88	        Reservation res = reservations.get(id);
    89	        if (res == null) {
    90	            throw new IllegalArgumentException("Reservation not found");
    91	        }
    92	
    93	        double refund = 0;
    94	        if (res.getStatus() == ReservationStatus.CONFIRMED) {
    95	            if (res.getRatePlan() == RatePlan.STANDARD) {
    96	                refund = res.getAmountPaid();
    97	            }
    98	        }
    99	
   100	        res.cancel(refund > 0 ? refund : null);
   101	        return res;
   102	    }
