   104	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   105	        LocalDate current = checkIn;
   106	        while (current.isBefore(checkOut)) {
   107	            final LocalDate checkDate = current;
   108	            boolean occupied = reservations.values().stream()
   109	                    .filter(r -> r.getRoomNumber() == roomNumber && r.getStatus() != ReservationStatus.CANCELLED)
   110	                    .anyMatch(r -> !r.getCheckIn().isAfter(checkDate) && r.getCheckOut().isAfter(checkDate));
   111	
   112	            if (occupied) {
   113	                return true;
   114	            }
   115	            current = current.plusDays(1);
   116	        }
   117	        return false;
   118	    }
   119	
   120	    public List<Reservation> getReservationsForRoom(int roomNumber, LocalDate date) {
   121	        return reservations.values().stream()
   122	                .filter(r -> r.getRoomNumber() == roomNumber && r.getStatus() != ReservationStatus.CANCELLED
   123	                        && !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
   124	                .toList();
   125	    }
   126	
   127	    public List<Reservation> getReservationsStartingInMonth(int year, int month) {
   128	        return reservations.values().stream()
   129	                .filter(r -> r.getCheckIn().getYear() == year && r.getCheckIn().getMonthValue() == month
   130	                        && (r.getStatus() == ReservationStatus.CONFIRMED || r.getStatus() == ReservationStatus.CHECKED_IN
   131	                                || r.getStatus() == ReservationStatus.CHECKED_OUT || r.getStatus() == ReservationStatus.CANCELLED)
   132	                        && r.getAmountPaid() > 0)
   133	                .sorted((a, b) -> {
   134	                    int dateCompare = a.getCheckIn().compareTo(b.getCheckIn());
   135	                    if (dateCompare == 0) {
   136	                        return Integer.compare(a.getId(), b.getId());
   137	                    }
   138	                    return dateCompare;
   139	                })
   140	                .toList();
   141	    }
   142	}
