   364	import com.pousada.domain.RatePlan;
   365	import com.pousada.util.MoneyRounder;
   366	import java.time.LocalDate;
   367	
   368	public class PricingService {
   369	    private static final double HIGH_SEASON_MULTIPLIER = 1.2;
   370	    private static final double NON_REFUNDABLE_DISCOUNT_RATE = 0.15;
   371	
   372	    public record PricingResult(int nights, double subtotal, double discount, double total) {
   373	    }
   374	
   375	    public PricingResult calculatePrice(double nightlyRate, LocalDate checkIn, LocalDate checkOut,
   376	            RatePlan ratePlan) {
   377	        int nights = (int) checkOut.toEpochDay() - (int) checkIn.toEpochDay();
   378	
   379	        double subtotal = 0;
   380	        LocalDate currentDate = checkIn;
   381	        while (currentDate.isBefore(checkOut)) {
   382	            double rate = nightlyRate;
   383	            if (isHighSeason(currentDate)) {
   384	                rate = MoneyRounder.round(rate * HIGH_SEASON_MULTIPLIER);
   385	            }
   386	            subtotal = MoneyRounder.round(subtotal + rate);
   387	            currentDate = currentDate.plusDays(1);
   388	        }
   389	
   390	        double discount = 0;
   391	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
   392	            discount = MoneyRounder.round(subtotal * NON_REFUNDABLE_DISCOUNT_RATE);
   393	        }
   394	
   395	        double total = MoneyRounder.round(subtotal - discount);
   396	
   397	        return new PricingResult(nights, subtotal, discount, total);
   398	    }
   399	
   400	    private boolean isHighSeason(LocalDate date) {
   401	        int month = date.getMonthValue();
   402	        int day = date.getDayOfMonth();
   403	
   404	        if (month == 7) {
   405	            return true;
   406	        }
   407	
   408	        if (month == 12 && day >= 15) {
   409	            return true;
   410	        }
   411	        if (month == 1 || month == 2) {
   412	            return true;
   413	        }
   414	
   415	        return false;
   416	    }
   417	}
