    46	        csv.append(String.format("total,%d/%d\n", occupiedRooms, roomService.getAllRooms().size()));
    47	
    48	        return csv.toString();
    49	    }
    50	
    51	    public String generateRevenueReport(int year, int month) {
    52	        StringBuilder csv = new StringBuilder();
    53	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    54	
    55	        double total = 0;
    56	
    57	        List<Reservation> reservations = reservationService.getReservationsStartingInMonth(year, month);
    58	
    59	        for (Reservation res : reservations) {
    60	            double amount = res.getAmountPaid();
    61	            if (res.getRefund() != null) {
    62	                amount -= res.getRefund();
    63	            }
    64	
    65	            csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n", res.getId(), res.getRoomNumber(),
    66	                    res.getCheckIn().toString(), res.getCheckOut().toString(), res.getStatus().name(), amount));
    67	
    68	            total += amount;
    69	        }
    70	
    71	        csv.append(String.format("total,%.2f\n", total));
    72	
    73	        return csv.toString();
    74	    }
