    83	import java.time.format.DateTimeParseException;
    84	
    85	public class ReportController {
    86	    private final ReportService reportService;
    87	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    88	
    89	    public ReportController(ReportService reportService) {
    90	        this.reportService = reportService;
    91	    }
    92	
    93	    public void registerRoutes(Javalin app) {
    94	        app.get("/reports/occupancy", this::getOccupancyReport);
    95	        app.get("/reports/revenue", this::getRevenueReport);
    96	    }
    97	
    98	    private void getOccupancyReport(io.javalin.http.Context ctx) {
    99	        String dateParam = ctx.queryParam("date");
   100	
   101	        if (dateParam == null) {
   102	            ctx.status(400);
   103	            ctx.json(new ErrorResponse("INVALID_REQUEST", "date parameter is required"));
   104	            return;
   105	        }
   106	
   107	        try {
   108	            LocalDate date = LocalDate.parse(dateParam, DATE_FORMAT);
   109	            String report = reportService.generateOccupancyReport(date);
   110	            ctx.header("Content-Type", "text/csv;charset=utf-8");
   111	            ctx.result(report);
   112	        } catch (DateTimeParseException e) {
   113	            ctx.status(400);
   114	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format, use yyyy-MM-dd"));
   115	        }
   116	    }
   117	
   118	    private void getRevenueReport(io.javalin.http.Context ctx) {
   119	        String monthParam = ctx.queryParam("month");
   120	
   121	        if (monthParam == null) {
   122	            ctx.status(400);
   123	            ctx.json(new ErrorResponse("INVALID_REQUEST", "month parameter is required"));
   124	            return;
   125	        }
   126	
   127	        try {
   128	            String[] parts = monthParam.split("-");
   129	            if (parts.length != 2) {
   130	                throw new NumberFormatException();
   131	            }
   132	            int year = Integer.parseInt(parts[0]);
   133	            int month = Integer.parseInt(parts[1]);
   134	
   135	            if (month < 1 || month > 12) {
   136	                ctx.status(400);
   137	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month"));
   138	                return;
   139	            }
   140	
   141	            String report = reportService.generateRevenueReport(year, month);
   142	            ctx.header("Content-Type", "text/csv;charset=utf-8");
   143	            ctx.result(report);
   144	        } catch (NumberFormatException e) {
   145	            ctx.status(400);
   146	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format, use yyyy-MM"));
   147	        }
   148	    }
   149	}
